package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateDueBy {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody DueByRequest request, Out<ValidDueBy> body, Settings settings)
            throws InvalidClaimException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String dueBy = request.dueBy() == null ? "" : request.dueBy().trim();
        try {
            body.set(new ValidDueBy(request.user(), LocalDate.parse(dueBy)));
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Setting a due-by needs the claim's new due-by");
        }
    }
}
EOF
cat > $D/ApplyDueBy.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * A steward sets the due-by of a DRAFT, OPEN or PENDING claim directly. The due-by stays as set: the claim no longer
 * keeps the terms it was fixed with, so a holiday added later does not move it. Overdue, the late charge, grace and
 * the claim's period follow it.
 */
public class ApplyDueBy {
    public void apply(@Val ValidDueBy request, @Val Claim claim, Settings settings, Out<ClaimDueBy> dueBy)
            throws ClaimStatusRefusedException {
        if (!Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()))) {
            throw new ClaimStatusRefusedException("Only a steward can set a claim's due-by");
        }
        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
                && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusRefusedException("Only a DRAFT, OPEN or PENDING claim can have its due-by set");
        }
        dueBy.set(new ClaimDueBy(claim.getDueBy()));
        claim.setDueBy(request.dueBy());
        claim.setTerms(null);
    }
}
EOF
cat > $D/SaveDueBy.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveDueBy {
    public void save(@Val Claim claim, Claims claims) {
        claims.setDueBy(claim);
    }
}
EOF
cat > $D/AuditClaimDueBySet.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;

public class AuditClaimDueBySet {
    public void audit(@Val ValidDueBy request, @Val Claim claim, @Val ClaimDueBy dueBy, People people, Audit audit,
            @Val RollupFigures before, Rollup rollup) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.recordOnCommit(ClaimAudit.line("CLAIM_DUE_BY_SET", request.user(), person, claim, claim.getNumber())
                + " old=" + (dueBy.old() == null ? "" : dueBy.old()) + " new=" + claim.getDueBy());
        rollup.recordChanges(claim.getSheetId(), request.user(), before);
    }
}
EOF
